$can = $d['canEdit'];
/** Render the module × action matrix. $state: id => 1/0 (role) or 'allow'/'deny' (dept/user); $base: id => 1/0 inherited. */
$renderMatrix = function (string $mode, array $state, array $base = []) use ($d, $cols, $can) {
    ?><div class="sl-tw"><table class="pm-mx" data-pm-mode="<?= h($mode) ?>"><thead><tr><th>Module</th><?php foreach ($cols as $c): ?><th><?= h($c) ?></th><?php endforeach; ?><th></th></tr></thead><tbody>
    <?php foreach ($d['matrix']['mods'] as $m): ?><tr data-pm-row><td><span class="row g10"><i class="ic ic-sm i-grid mut" aria-hidden="true"></i><?= h($m['label']) ?> <span class="mut sm">(<?= (int) $m['n'] ?>)</span></span></td><?php foreach ($cols as $c): ?><td><div class="row g4 wrap" style="justify-content:center"><?php foreach ($m['cells'][$c] as $a): $st = $state[$a['id']] ?? ($mode === 'role' ? 0 : 'inherit'); $inh = $base[$a['id']] ?? 0;
        $cls = $mode === 'role' ? ($st ? 'on' : '') : ($st === 'allow' ? 'on' : ($st === 'deny' ? 'deny' : ($inh ? 'inh' : '')));
        ?><button type="button" class="pm-c <?= $cls ?><?= $can ? '' : ' na' ?>" data-pm-id="<?= (int) $a['id'] ?>" data-pm-state="<?= h((string) $st) ?>" data-pm-inh="<?= (int) $inh ?>" title="<?= h($a['name'] . ' — ' . $a['desc']) ?>" aria-label="<?= h($a['desc']) ?>" <?= $can ? '' : 'disabled' ?>><i class="ic ic-sm i-check" aria-hidden="true"></i></button><?php endforeach; ?></div></td><?php endforeach; ?><td><?php if ($can): ?><button type="button" class="pm-row-all" data-pm-all>All</button><?php endif; ?></td></tr><?php endforeach; ?>
    </tbody></table></div><?php
};
?>
