<script>
(function () {
  var copyOf = <?= json_encode(array_combine(array_column($d['roles'], 'id'), array_map(fn($r) => $r['allowed'], $d['roles']))) ?>;
  var nameOf = <?= json_encode(array_combine(array_map(fn($m) => array_merge(...array_values($m['cells'])), $d['matrix']['mods']) ? array_merge(...array_map(fn($m) => array_column(array_merge(...array_values($m['cells'])), 'id'), $d['matrix']['mods'])) : [], array_merge(...array_map(fn($m) => array_column(array_merge(...array_values($m['cells'])), 'name'), $d['matrix']['mods'])) ?: [])) ?>;
  var moneyId = <?= (int) (array_values(array_filter($d['sens'], fn($x) => $x['name'] === 'view_financial_overview'))[0]['id'] ?? 0) ?>;
  function setRole(b, on) { b.classList.toggle('on', on); b.setAttribute('data-pm-state', on ? '1' : '0'); }
  function cycle(b) { var s = b.getAttribute('data-pm-state'); var n = s === 'inherit' ? 'allow' : (s === 'allow' ? 'deny' : 'inherit'); b.setAttribute('data-pm-state', n); b.classList.toggle('on', n === 'allow'); b.classList.toggle('deny', n === 'deny'); b.classList.toggle('inh', n === 'inherit' && b.getAttribute('data-pm-inh') === '1'); }
  function count() { var el = document.querySelector('[data-pm-count]'); if (!el) return; var n = document.querySelectorAll('#pm-role-matrix .pm-c.on').length; el.textContent = n + ' of ' + document.querySelectorAll('#pm-role-matrix .pm-c').length + ' switched on'; }
  function syncMoney() { var b = document.querySelector('#pm-role-matrix .pm-c[data-pm-id="' + moneyId + '"]'); var sw = document.querySelector('[data-pm-sens="' + moneyId + '"]'); var on = b ? b.classList.contains('on') : false; if (sw) { sw.classList.toggle('on', on); sw.setAttribute('aria-checked', on ? 'true' : 'false'); } document.querySelectorAll('#pm-prev .big').forEach(function (x) { x.classList.toggle('pm-blur', !on); }); var l = document.getElementById('pm-lock'); if (l) l.hidden = on; }
  document.addEventListener('click', function (e) {
    var c = e.target.closest('.pm-c'); if (c && !c.disabled) { var t = c.closest('table'); if (t.getAttribute('data-pm-mode') === 'role') setRole(c, !c.classList.contains('on')); else cycle(c); count(); syncMoney(); return; }
    var all = e.target.closest('[data-pm-all]'); if (all) { var row = all.closest('tr'), cells = row.querySelectorAll('.pm-c'), mode = row.closest('table').getAttribute('data-pm-mode'); var anyOff = Array.prototype.some.call(cells, function (b) { return mode === 'role' ? !b.classList.contains('on') : b.getAttribute('data-pm-state') !== 'allow'; }); cells.forEach(function (b) { if (mode === 'role') setRole(b, anyOff); else { b.setAttribute('data-pm-state', anyOff ? 'allow' : 'inherit'); b.classList.toggle('on', anyOff); b.classList.remove('deny'); b.classList.toggle('inh', !anyOff && b.getAttribute('data-pm-inh') === '1'); } }); count(); syncMoney(); return; }
    var sw = e.target.closest('[data-pm-sens]'); if (sw && !sw.disabled) { var b = document.querySelector('#pm-role-matrix .pm-c[data-pm-id="' + sw.getAttribute('data-pm-sens') + '"]'); if (b) { setRole(b, !b.classList.contains('on')); } else { sw.classList.toggle('on'); } count(); syncMoney(); return; }
    var p = e.target.closest('[data-pm-preset]'); if (p) { var kind = p.getAttribute('data-pm-preset'); document.querySelectorAll('#pm-role-matrix .pm-c').forEach(function (b) { var nm = nameOf[b.getAttribute('data-pm-id')] || ''; setRole(b, kind === 'all' || (kind === 'view' && /^(view|list|track|prealert_list|main_dashboard)/.test(nm))); }); count(); syncMoney(); return; }
    var cp = e.target.closest('[data-pm-copy]'); if (cp) { var allowed = copyOf[cp.getAttribute('data-pm-copy')] || []; document.querySelectorAll('#pm-role-matrix .pm-c').forEach(function (b) { setRole(b, allowed.indexOf(nameOf[b.getAttribute('data-pm-id')]) >= 0); }); count(); syncMoney(); return; }
    var s = e.target.closest('[data-pm-save]'); if (s) {
      var mode = s.getAttribute('data-pm-save'), data = { op: mode === 'role' ? 'role_save' : (mode === 'dept' ? 'dept_save' : 'user_save') };
      if (mode === 'role') { var box = document.getElementById('pm-role-matrix'); data.role_id = box.getAttribute('data-role'); data.granted = Array.prototype.map.call(box.querySelectorAll('.pm-c.on'), function (b) { return b.getAttribute('data-pm-id'); }).join(','); }
      else { var box2 = document.getElementById(mode === 'dept' ? 'pm-dept-matrix' : 'pm-user-matrix'); data[mode === 'dept' ? 'department_id' : 'user_id'] = box2.getAttribute(mode === 'dept' ? 'data-dept' : 'data-user'); var ch = {}; box2.querySelectorAll('.pm-c').forEach(function (b) { ch[b.getAttribute('data-pm-id')] = b.getAttribute('data-pm-state'); }); data.changes = JSON.stringify(ch); }
      s.classList.add('loading'); SL.post('ajax/sl/staff_permissions_ajax.php', data).then(function (j) { SL.toast(j.message || (j.success ? 'Saved' : 'Failed'), !j.success); if (j.success) setTimeout(function () { location.reload(); }, 400); }).catch(function () { SL.toast('Network error', true); }).finally(function () { s.classList.remove('loading'); });
    }
  });
  document.addEventListener('change', function (e) { var sel = e.target.closest('[data-pm-role-change]'); if (!sel || !sel.value) return; if (!confirm('Change this person\'s role?')) { sel.value = ''; return; } SL.post('ajax/sl/staff_permissions_ajax.php', { op: 'user_role', user_id: sel.getAttribute('data-pm-role-change'), role_id: sel.value }).then(function (j) { SL.toast(j.message || '', !j.success); if (j.success) setTimeout(function () { location.reload(); }, 400); }); });
})();
</script>
<style>.pm-c.inh{background:var(--line-2);border-color:var(--line-2)}.pm-c.deny{background:var(--red-bg);border-color:var(--red);color:var(--red-ink)}.pm-c.deny .ic{opacity:1}</style>
